  q.memcpy(Y.data(), dY, m*n*sizeof(float)).wait();
  md = 0; for (int i = 0; i < m*n; i++) md = fmax(md, fabs(Y[i]-(ref[i]+1.0f)));
  printf("accum maxdiff=%.6f %s\n", md, md < 1e-3 ? "OK" : "BAD");

  // big classifier-like shape timing: 256 x 768 x 50304
  {
    const int64_t bm=256, bk=768, bn=50304;
    bf16* bX = sycl::malloc_device<bf16>(bm*bk, q);
    bf16* bW = sycl::malloc_device<bf16>(bn*bk, q);
    float* bY = sycl::malloc_device<float>(bm*bn, q);
    q.memset(bX, 0, bm*bk*sizeof(bf16)); q.memset(bW, 0, bn*bk*sizeof(bf16)); q.wait();
    auto t0 = std::chrono::high_resolution_clock::now();
    oneapi::math::blas::column_major::gemm(q,
      oneapi::math::transpose::trans, oneapi::math::transpose::nontrans,
      bn, bm, bk, 1.0f, bW, bk, bX, bk, 0.0f, bY, bn);
    q.wait();
    auto t1 = std::chrono::high_resolution_clock::now();
    double ms = std::chrono::duration<double,std::milli>(t1-t0).count();
    double gflop = 2.0*bm*bn*bk/1e9;
    printf("big gemm: %.1f ms %.1f GFLOP -> %.1f GFLOPS\n", ms, gflop, gflop/(ms/1e3));
    sycl::free(bX, q); sycl::free(bW, q); sycl::free(bY, q);
  }
  return 0;
}

#include <sycl/sycl.hpp>
#include <sycl/ext/oneapi/bfloat16.hpp>
#include <oneapi/math/blas.hpp>
#include <cstdio>
#include <vector>
#include <cmath>
using bf16 = sycl::ext::oneapi::bfloat16;

// row-major Y(m x n) = X(m x k) * W(n x k)^T
void gemm_fwd(sycl::queue& q, float* Y, const bf16* X, const bf16* W,
              int64_t m, int64_t n, int64_t k, float beta = 0.f) {
  oneapi::math::blas::column_major::gemm(q,
    oneapi::math::transpose::trans, oneapi::math::transpose::nontrans,
    n, m, k, 1.0f, W, k, X, k, beta, Y, n);
  q.wait();
}
// row-major DW(C x OC) = IN(BT x C)^T * DOUT(BT x OC)
void gemm_dweight(sycl::queue& q, float* DW, const bf16* IN, const bf16* DOUT,
                  int64_t BT, int64_t C, int64_t OC, float beta = 0.f) {
  oneapi::math::blas::column_major::gemm(q,
    oneapi::math::transpose::nontrans, oneapi::math::transpose::trans,
    OC, C, BT, 1.0f, DOUT, OC, IN, C, beta, DW, OC);
  q.wait();
}
// row-major DIN(BT x C) = DOUT(BT x OC) * W(OC x C)
void gemm_din(sycl::queue& q, float* DIN, const bf16* DOUT, const bf16* W,
              int64_t BT, int64_t C, int64_t OC) {
  oneapi::math::blas::column_major::gemm(q,
    oneapi::math::transpose::trans, oneapi::math::transpose::nontrans,
    C, BT, OC, 1.0f, W, OC, DOUT, OC, 0.0f, DIN, C);
  q.wait();
}

int main() {
  sycl::queue q;
  printf("dev: %s\n", q.get_device().get_info<sycl::info::device::name>().c_str());
  const int m = 5, k = 9, n = 7;
  std::vector<float> Xf(m*k), Wf(n*k);
  for (int i = 0; i < m*k; i++) Xf[i] = 0.1f*((i*37)%11-5);
  for (int i = 0; i < n*k; i++) Wf[i] = 0.1f*((i*53)%13-6);
  std::vector<bf16> X(m*k), W(n*k);
  for (int i = 0; i < m*k; i++) X[i] = bf16(Xf[i]);
  for (int i = 0; i < n*k; i++) W[i] = bf16(Wf[i]);
  bf16 *dX = sycl::malloc_device<bf16>(m*k, q);
  bf16 *dW = sycl::malloc_device<bf16>(n*k, q);
  float *dY = sycl::malloc_device<float>(m*n, q);
  float *dDW = sycl::malloc_device<float>(k*n, q);
  float *dDIN = sycl::malloc_device<float>(m*k, q);
  q.memcpy(dX, X.data(), m*k*sizeof(bf16));
  q.memcpy(dW, W.data(), n*k*sizeof(bf16));
  q.wait();
  // ref fwd in fp32 from bf16 values
  std::vector<float> Xb(m*k), Wb(n*k);
  for (int i = 0; i < m*k; i++) Xb[i] = (float)X[i];
  for (int i = 0; i < n*k; i++) Wb[i] = (float)W[i];
  std::vector<float> ref(m*n, 0);
  for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) {
    double s = 0; for (int p = 0; p < k; p++) s += (double)Xb[i*k+p]*(double)Wb[j*k+p];
    ref[i*n+j] = s;
  }
  std::vector<float> Y(m*n);
  gemm_fwd(q, dY, dX, dW, m, n, k);
  q.memcpy(Y.data(), dY, m*n*sizeof(float)).wait();
  double md = 0; for (int i = 0; i < m*n; i++) md = fmax(md, fabs(Y[i]-ref[i]));
  printf("fwd maxdiff=%.6f %s\n", md, md < 1e-3 ? "OK" : "BAD");

  // dweight: DW[i][j] = sum_p Xb[p][i]*Db[p][j], Db = bf16(Y-ish)
  std::vector<bf16> Db(m*n);
  std::vector<float> Dbf(m*n);
  for (int i = 0; i < m*n; i++) { Db[i] = bf16(0.05f*((i*29)%7-3)); Dbf[i] = (float)Db[i]; }
  bf16* dD = sycl::malloc_device<bf16>(m*n, q);
  q.memcpy(dD, Db.data(), m*n*sizeof(bf16)).wait();
  std::vector<float> refW(k*n, 0);
  for (int i = 0; i < k; i++) for (int j = 0; j < n; j++) {
    double s = 0; for (int p = 0; p < m; p++) s += (double)Xb[p*k+i]*(double)Dbf[p*n+j];
    refW[i*n+j] = s;
  }
  std::vector<float> DW(k*n);
  gemm_dweight(q, dDW, dX, dD, m, k, n);
  q.memcpy(DW.data(), dDW, k*n*sizeof(float)).wait();
  md = 0; for (int i = 0; i < k*n; i++) md = fmax(md, fabs(DW[i]-refW[i]));
  printf("dweight maxdiff=%.6f %s\n", md, md < 1e-3 ? "OK" : "BAD");

  // din
  std::vector<float> refIN(m*k, 0);
  for (int i = 0; i < m; i++) for (int j = 0; j < k; j++) {
    double s = 0; for (int p = 0; p < n; p++) s += (double)Dbf[i*n+p]*(double)Wb[p*k+j];
    refIN[i*k+j] = s;
  }
  std::vector<float> DIN(m*k);
  gemm_din(q, dDIN, dD, dW, m, k, n);
  q.memcpy(DIN.data(), dDIN, m*k*sizeof(float)).wait();
  md = 0; for (int i = 0; i < m*k; i++) md = fmax(md, fabs(DIN[i]-refIN[i]));
  printf("din maxdiff=%.6f %s\n", md, md < 1e-3 ? "OK" : "BAD");

  // beta=1 accumulate
  std::vector<float> Y0(m*n, 1.0f);
  q.memcpy(dY, Y0.data(), m*n*sizeof(float)).wait();
  gemm_fwd(q, dY, dX, dW, m, n, k, 1.0f);
  q.memcpy(Y.data(), dY, m*n*sizeof(float)).wait();
  md = 0; for (int i = 0; i < m*n; i++) md = fmax(md, fabs(Y[i]-(ref[i]+1.0f)));
  printf("accum maxdiff=%.6f %s\n", md, md < 1e-3 ? "OK" : "BAD");

  // big classifier-like shape timing: 256 x 768 x 50304
  {
    const int64_t bm=256, bk=768, bn=50304;
    bf16* bX = sycl::malloc_device<bf16>(bm*bk, q);
    bf16* bW = sycl::malloc_device<bf16>(bn*bk, q);
    float* bY = sycl::malloc_device<float>(bm*bn, q);
    q.memset(bX, 0, bm*bk*sizeof(bf16)); q.memset(bW, 0, bn*bk*sizeof(bf16)); q.wait();
    auto t0 = std::chrono::high_resolution_clock::now();
    oneapi::math::blas::column_major::gemm(q,
      oneapi::math::transpose::trans, oneapi::math::transpose::nontrans,
      bn, bm, bk, 1.0f, bW, bk, bX, bk, 0.0f, bY, bn);
    q.wait();
    auto t1 = std::chrono::high_resolution_clock::now();
    double ms = std::chrono::duration<double,std::milli>(t1-t0).count();
    double gflop = 2.0*bm*bn*bk/1e9;
    printf("big gemm: %.1f ms %.1f GFLOP -> %.1f GFLOPS\n", ms, gflop, gflop/(ms/1e3));
    sycl::free(bX, q); sycl::free(bW, q); sycl::free(bY, q);
  }
  return 0;
}

