// ----------------------------------------------------------------------------
// Bias epilogue kernels (forward: add bias; backward: sum bias grads)

// out[i*OC+j] = f32[i*OC+j] + bias[j]; then stochastic-round/store to bf16 `outX`
inline void bias_add_forward(floatX* outX, const float* f32, const floatX* bias,
                             size_t BT, size_t OC, sycl::queue& q, unsigned int seed) {
    constexpr size_t BLOCK = 256;
    size_t total = BT * OC;
    size_t nblocks = CEIL_DIV(total, BLOCK);
    q.parallel_for(sycl::range<1>(nblocks * BLOCK), [=](sycl::id<1> id) {
        size_t lin = id[0];
        if (lin >= total) { return; }
        size_t j = lin % OC;
        float v = f32[lin] + (float)bias[j];
        if constexpr (std::is_same<floatX, float>::value) {
            outX[lin] = v;
        } else {
            unsigned int random = Get2dNoiseUint((int)(lin % 1024), (int)(lin / 1024), seed);
            outX[lin] = stochastic_rounding_bf16(v, random);
        }
    }).wait();
}

// out[i*OC+j] = f32[i*OC+j] (convert fp32 GEMM output to floatX, no bias)
inline void convert_forward(floatX* outX, const float* f32, size_t N, sycl::queue& q, unsigned int seed) {
    constexpr size_t BLOCK = 256;
    size_t nblocks = CEIL_DIV(N, BLOCK);
    q.parallel_for(sycl::range<1>(nblocks * BLOCK), [=](sycl::id<1> id) {
        size_t lin = id[0];
        if (lin >= N) { return; }
        if constexpr (std::is_same<floatX, float>::value) {
            outX[lin] = f32[lin];
        } else {
            unsigned int random = Get2dNoiseUint((int)(lin % 1024), (int)(lin / 1024), seed);
            outX[lin] = stochastic_rounding_bf16(f32[lin], random);
        }
    }).wait();
}

// dbias[j] += sum_i dout[i*OC+j]  (deterministic: single work-group tree per j via atomics-free staged sum)
// Simple deterministic implementation: each j reduced by a single group sequentially is too slow;
// instead do a two-stage deterministic sum: partial sums per block, then single-group final sum.
inline void bias_backward_sum(floatX* dbias, const floatX* dout, size_t BT, size_t OC, sycl::queue& q) {
    // stage 1: partial sums, PB blocks
    constexpr size_t BLOCK = 256;
    size_t PB = 64;
    if (BT < 64) { PB = 1; }
    float* partial = sycl::malloc_device<float>(PB * OC, q);
    q.memset(partial, 0, PB * OC * sizeof(float)).wait();
    // each block handles a shard of rows; all OC columns
    q.parallel_for(sycl::range<1>(PB * BLOCK), [=](sycl::id<1> id) {
        size_t tid = id[0] % BLOCK;
        size_t pb = id[0] / BLOCK;
        size_t rows_per = (BT + PB - 1) / PB;
        size_t r0 = pb * rows_per;
        size_t r1 = sycl::min(r0 + rows_per, BT);
        for (size_t j = tid; j < OC; j += BLOCK) {
            float s = 0.f;
            for (size_t i = r0; i < r1; i++) {
                s += (float)dout[i * OC + j];
            }
            partial[pb * OC + j] = s;
        }
    }).wait();
    // stage 2: deterministic sum over PB partials + accumulate into dbias
    {
        size_t nblocks = CEIL_DIV(OC, BLOCK);
        q.parallel_for(sycl::range<1>(nblocks * BLOCK), [=](sycl::id<1> id) {
            size_t j = id[0];
            if (j >= OC) { return; }
            float s = 0.f;
            for (size_t pb = 0; pb < PB; pb++) { s += partial[pb * OC + j]; }
            dbias[j] = (floatX)((float)dbias[j] + s);
        }).wait();
    }
    sycl::free(partial, q);
}

// reduce fp32 partial rows (rows x OC) into floatX dbias (+=)
inline void reduce_add_sum_kernel_sycl(floatX* dst, const float* src, size_t n, size_t m, sycl::queue& q) {
    constexpr size_t BLOCK = 256;
    size_t nblocks = CEIL_DIV(n, BLOCK);
    q.parallel_for(sycl::range<1>(nblocks * BLOCK), [=](sycl::id<1> id) {
        size_t idx = id[0];
        if (idx >= n) { return; }
        float acc = 0.f;
        for (size_t l = 0; l < m; l++) { acc += src[idx + n * l]; }
        dst[idx] = (floatX)((float)dst[idx] + acc);
    }).wait();
}

// ----------------------------------------------------------------------------
// High-level matmul forward/backward (API mirrors the CUDA file)

// scratchF32 must hold BT*OC floats (caller provides, e.g. acts.output as float*)
inline void matmul_forward_sycl(floatX* out, float* scratchF32,
                                const floatX* inp, const floatX* weight, const floatX* bias,
                                int B, int T, int C, int OC, sycl::queue& q, unsigned int seed=0) {
    NVTX_RANGE_FN();
    size_t BT = (size_t)B * T;
    sycl_gemm_forward(scratchF32, inp, weight, BT, OC, C, 0.0f, q);
    if (bias != nullptr) {
        bias_add_forward(out, scratchF32, bias, BT, OC, q, seed);
    } else {
        convert_forward(out, scratchF32, BT * OC, q, seed);
    }
}

// GELU-fused forward: computes pre_gelu = inp*W+bias (fp32->floatX), then gelu into out
inline void matmul_forward_gelu_sycl(floatX* out, floatX* pre_gelu, float* scratchF32,
                                     const floatX* inp, const floatX* weight, const floatX* bias,
                                     int B, int T, int C, int OC, sycl::queue& q, unsigned int seed=0) {
    NVTX_RANGE_FN();
    size_t BT = (size_t)B * T;
    sycl_gemm_forward(scratchF32, inp, weight, BT, OC, C, 0.0f, q);
    if (bias != nullptr) {
        bias_add_forward(pre_gelu, scratchF32, bias, BT, OC, q, seed);
    } else {
        convert_forward(pre_gelu, scratchF32, BT * OC, q, seed);
    }
    gelu_forward(out, pre_gelu, BT * OC, q);
}

// dout: (BT x OC) floatX; inp: (BT x C); weight: (OC x C)
// dinp: (BT x C) floatX (set); dweight: (C x OC) floatX (+=); dbias: (OC) floatX (+=, optional)
inline void matmul_backward_sycl(floatX* dinp, floatX* dweight, floatX* dbias,
                                 const floatX* dout, const floatX* inp, const floatX* weight,
                                 int B, int T, int C, int OC, sycl::queue& q,
                                 const floatX* pre_gelu = nullptr) {
    NVTX_RANGE_FN();
    size_t BT = (size_t)B * T;
    // backward to bias (+=), deterministic
    if (dbias != nullptr) {
        bias_backward_sum(dbias, dout, BT, OC, q);
    }
    // backward to input (=): need fp32 intermediate then convert
    {
        float* dinF = sycl::malloc_device<float>(BT * (size_t)C, q);
        sycl_gemm_din(dinF, dout, weight, BT, C, OC, q);
        if (pre_gelu != nullptr) {
            // apply gelu backward inplace on fp32? No: gelu backward needs floatX pre and din.
            // Convert dinF to floatX first, then apply gelu_backward_inplace.
            convert_forward(dinp, dinF, BT * (size_t)C, q, 0);
            gelu_backward_inplace(dinp, pre_gelu, BT * (size_t)C, q);
        } else {
            convert_forward(dinp, dinF, BT * (size_t)C, q, 0);
        }
        sycl::free(dinF, q);
    }
    // backward to weight (+=): fp32 accumulate then round-add into dweight
    {
        float* dwF = sycl::malloc_device<float>((size_t)C * OC, q);
        q.memset(dwF, 0, (size_t)C * OC * sizeof(float)).wait();
        sycl_gemm_dweight(dwF, inp, dout, BT, C, OC, 0.0f, q);
        // dwF is row-major (C x OC); dweight same layout: dweight += round(dwF)
        size_t N = (size_t)C * OC;
        constexpr size_t BLOCK = 256;
        size_t nblocks = CEIL_DIV(N, BLOCK);
        q.parallel_for(sycl::range<1>(nblocks * BLOCK), [=](sycl::id<1> id) {
            size_t i = id[0];
            if (i >= N) { return; }
            float v = (float)dweight[i] + dwF[i];
            if constexpr (std::is_same<floatX, float>::value) {
                dweight[i] = v;
            } else {
                dweight[i] = sycl_float_to_bf16_rn(v);
            }
        }).wait();
        sycl::free(dwF, q);
    }
}

#endif

/*
The GPT-2 Encoder: token + position encodings (SYCL port of encoder.cuh)
*/
#ifndef ENCODER_SYCL_H
#define ENCODER_SYCL_H

#include <assert.h>
#include <stdint.h>
#include <utility>
#include <vector>
#include <algorithm>
#include <unordered_map>
#include <sycl/sycl.hpp>
// llmc internal imports
#include "sycl_common.h"
#include "sycl_utils.h"

// ----------------------------------------------------------------------------
// SYCL kernels

inline void encoder_forward(floatX* out,
                            const int* inp, const floatX* wte, const floatX* wpe,
                            int B, int T, int C, sycl::queue& q) {
    NVTX_RANGE_FN();
    size_t N = (size_t)B * T * C;
    constexpr size_t BLOCK = 256;
    size_t nblocks = CEIL_DIV(N, BLOCK);
    q.parallel_for(sycl::range<1>(nblocks * BLOCK), [=](sycl::id<1> id) {
        size_t idx = id[0];
        if (idx >= N) { return; }
        size_t bt = idx / (size_t)C;
        size_t b = bt / (size_t)T;
        size_t t = bt % (size_t)T;
        size_t c = idx % (size_t)C;
        int ix = inp[b * (size_t)T + t];
        out[idx] = (floatX)((float)wte[(size_t)ix * C + c] + (float)wpe[t * (size_t)C + c]);
    }).wait();
}

// Fully deterministic wte backward using CPU bucketing (same algorithm as CUDA version).
// dout: (B*T*C), dwte: (Vp*C) updated with stochastic rounding read-modify-write.
inline void wte_backward_sycl(floatX* dwte,
                              const int* bucket_info, const int* workload_indices,
                              const floatX* dout,
                              unsigned int seed, int B, int T, int C, int num_buckets, sycl::queue& q) {
    // One work-group (sub-group cooperatively) per bucket-channel-group.
    // Simplify vs CUDA: each (bucket) handled by 256 threads processing items in order.
    constexpr size_t BLOCK = 256;
    // copy bucket info to device already done by caller; here bucket_info layout: [start, size, ix, c] x num_buckets
    // For determinism, accumulate per (bucket) in fixed item order, then stochastic round once.
    // Each bucket may span multiple channel-vectors; handle per-lane below.
    // We launch num_buckets * Cgroups? No: bucket already encodes c-group. Each bucket -> BLOCK threads.
    // Within a bucket, thread t handles channel offset (t % 32)*8+k style for bf16 (x8 per 128-bit). Generalize: 8-wide chunks.
    size_t total = (size_t)num_buckets * BLOCK;
    // We need C per bucket to know vector width; pass via closure.
    q.parallel_for(sycl::nd_range<1>(sycl::range<1>(total), sycl::range<1>(BLOCK)),
        [=](sycl::nd_item<1> item) {
        size_t bucket = item.get_group(0);
        size_t tid = item.get_local_id(0);
        int bstart = bucket_info[bucket * 4 + 0];
        int bsize = bucket_info[bucket * 4 + 1];
        int bix = bucket_info[bucket * 4 + 2];
        int bc = bucket_info[bucket * 4 + 3];
        // channels per thread chunk: 8 for bf16 (matches x128::size=8), 4 for fp32
        constexpr int CH = (sizeof(floatX) == 2) ? 8 : 4;
        constexpr int LANES = 32;
        int c_per_group = LANES * CH;
        int lane = (int)(tid % LANES);
        int c = bc * c_per_group + lane * CH;
        if (c >= C) { return; }
        // accumulate over items assigned round-robin deterministically then tree-reduce in order
        // First: each thread sums its strided items in index order.
        int nwarps_items = (int)((BLOCK / LANES)); // 8 "warps" per block like CUDA (256/32)
        int warp_id = (int)(tid / LANES);
        float accum[8] = {0,0,0,0,0,0,0,0};
        for (int item_i = warp_id; item_i < bsize; item_i += nwarps_items) {
            int bt = workload_indices[bstart + item_i];
            const floatX* row = dout + (size_t)bt * C + c;
            for (int k = 0; k < CH; k++) {
                if (c + k < C) { accum[k] += (float)row[k]; }
            }
        }
        // shared memory reduction across warps in fixed order (warp 0 += warp 1 += ...)
        sycl::local_accessor<float, 1> sh(sycl::range<1>(BLOCK * 8), item);
        for (int k = 0; k < CH; k++) { sh[tid * 8 + k] = accum[k]; }
        item.barrier(sycl::access::fence_space::local_space);
        if (warp_id != 0) { return; }
        // warp 0: read-modify-write with stochastic rounding
        floatX* drow = dwte + (size_t)bix * C + c;
        for (int k = 0; k < CH; k++) {
            if (c + k >= C) { break; }
            float s = accum[k];
            for (int w = 1; w < nwarps_items; w++) {
                s += sh[(w * LANES + lane) * 8 + k];
            }
            float cur = (float)drow[k];
            float v = s + cur;
            if constexpr (std::is_same<floatX, float>::value) {
                drow[k] = v;
            } else {
                unsigned int random = Get2dNoiseUint((int)(tid + k), (int)(bucket * 32 + lane), seed + (unsigned int)bucket * 32u + (unsigned int)tid + (unsigned int)k);
                drow[k] = stochastic_rounding_bf16(v, random);
            }
        }
    }).wait();
}

inline void wpe_backward_sycl(floatX* dwpe, const floatX* dout,
                              int B, int T, int C, unsigned int seed, sycl::queue& q) {
    size_t N = (size_t)T * C;
    constexpr size_t BLOCK = 256;
    size_t nblocks = CEIL_DIV(N, BLOCK);
    q.parallel_for(sycl::range<1>(nblocks * BLOCK), [=](sycl::id<1> id) {
        size_t idx = id[0];
        if (idx >= N) { return; }
        size_t t = idx / (size_t)C;
        size_t c = idx % (size_t)C;
        float acc = 0.f;
        for (int b = 0; b < B; b++) {
            acc += (float)dout[(size_t)b * T * C + t * (size_t)C + c];
        }
        floatX* p = dwpe + t * (size_t)C + c;
        float v = acc + (float)(*p);
        if constexpr (std::is_same<floatX, float>::value) {
            *p = v;
        } else {
            unsigned int random = Get2dNoiseUint((int)(idx % 1024), (int)(idx / 1024), seed + (unsigned int)idx);
            *p = stochastic_rounding_bf16(v, random);
        }
    }).wait();
}

// ----------------------------------------------------------------------------
// launchers

// Fully deterministic (see comments in CUDA file for details)
inline void encoder_backward(floatX* dwte, floatX* dwpe, floatX* scratch, // device outputs & scratch
                             int* workload_indices, int* bucket_info,      // cpu scratch buffers (int[4] per bucket)
                             const floatX* dout, const int* inp, const int* inputs_cpu,
                             int B, int T, int C, unsigned int seed, sycl::queue& q) {
    NVTX_RANGE_FN();

    // Launch wpe first (runs on device while CPU pre-processes wte buckets)
    wpe_backward_sycl(dwpe, dout, B, T, C, seed, q);

    constexpr int LANES = 32;
    constexpr int CH = (sizeof(floatX) == 2) ? 8 : 4;
    int num_c_groups = (int)CEIL_DIV(C, CH * LANES);

    // Step 1: Sort inputs into buckets
    int total_items = 0;
    std::unordered_map<uint64_t, std::vector<uint64_t>> buckets;
    for (uint64_t bt = 0; bt < (uint64_t)(B * T); bt++) {
        for (uint64_t c_group = 0; c_group < (uint64_t)num_c_groups; c_group++) {
            uint64_t data = bt + (c_group << 32ULL) + ((uint64_t)(uint32_t)inputs_cpu[bt] << 42ULL);
            buckets[c_group + (uint64_t)num_c_groups * (uint64_t)(uint32_t)inputs_cpu[bt]].push_back(data);
            total_items++;
        }
    }

    // Step 2: Sort buckets by size in descending order
    std::vector<std::pair<uint64_t, std::vector<uint64_t>>> sortedBuckets(buckets.begin(), buckets.end());
    std::sort(sortedBuckets.begin(), sortedBuckets.end(),
              [](const std::pair<uint64_t, std::vector<uint64_t>>& a,
                 const std::pair<uint64_t, std::vector<uint64_t>>& b) {
                  return a.second.size() > b.second.size();
              });

    int num_buckets = (int)buckets.size();
    int bucket_index = 0;
    int workload_index = 0;
    for (const auto& bucket : sortedBuckets) {
        bucket_info[bucket_index * 4 + 0] = workload_index;
        bucket_info[bucket_index * 4 + 1] = (int)bucket.second.size();
        bucket_info[bucket_index * 4 + 2] = (int)((bucket.second[0] >> 42ULL) & ((1ULL << 20ULL) - 1));
        bucket_info[bucket_index * 4 + 3] = (int)((bucket.second[0] >> 32ULL) & ((1ULL << 10ULL) - 1));
        for (uint64_t idx : bucket.second) {
            workload_indices[workload_index++] = (int)(idx & ((1ULL << 31ULL) - 1ULL));
        }
        bucket_index++;
    }

    // Step 3: Copy data host->device
    int* d_bucket_info = (int*)scratch;
    int* d_workload_indices = (int*)(scratch + (size_t)B * T * num_c_groups * sizeof(int) * 4 / sizeof(floatX));
    // NOTE: scratch is floatX*; compute byte offsets carefully:
    d_bucket_info = (int*)scratch;
    d_workload_indices = (int*)((char*)scratch + (size_t)B * T * num_c_groups * sizeof(int) * 4);
    q.memcpy(d_bucket_info, bucket_info, (size_t)num_buckets * 4 * sizeof(int)).wait();
    q.memcpy(d_workload_indices, workload_indices, (size_t)total_items * sizeof(int)).wait();

    wte_backward_sycl(dwte, d_bucket_info, d_workload_indices, dout, seed, B, T, C, num_buckets, q);
    (void)inp;
}

#endif

