        dm = sycl::reduce_over_group(sg, dm, sycl::plus<float>());
        dnm = sycl::reduce_over_group(sg, dnm, sycl::plus<float>());
        dm /= (float)C;
        dnm = dnm / (float)C * rstd_bt - dm * mean_bt * rstd_bt;
        // dinp (+=) and per-thread partial sums for bias/weight
        float pb = 0.f, pw = 0.f;
        // we need per-column partials; accumulate into shard buffers with one atomic-free pass:
        // each thread handles strided columns and writes its sums into partial buffers via strided adds.
        // To stay deterministic, partial buffers are zeroed and each (shard, col) is written by exactly one thread.
        for (int c = (int)lid; c < C; c += (int)WG) {
            float dout_i = (float)dout_bt[c];
            float norm_bti = ((float)inp_bt[c] - mean_bt) * rstd_bt;
            float dval = (float)weight[c] * dout_i - dm - norm_bti * dnm;
            dval *= rstd_bt;
            dinp_bt[c] = (floatX)((float)dinp_bt[c] + dval);
            part_bias[shard * (size_t)C + c] += dout_i;
            part_weight[shard * (size_t)C + c] += norm_bti * dout_i;
        }
        (void)pb; (void)pw;
    }).wait();
    // Stage 2: deterministic sum over shards into dweight/dbias (+=, stochastic-free plain accumulate in fp32 then round)
    {
        constexpr size_t BLOCK = 256;
        size_t nblocks = CEIL_DIV((size_t)C, BLOCK);
        q.parallel_for(sycl::range<1>(nblocks * BLOCK), [=](sycl::id<1> id) {
