    sycl_gemm_batch_preatt(preatt, kk, qq, T, HS, (int64_t)B * NH, q_);

    float scale = 1.f / sqrtf((float)HS);
    softmax_forward_sycl(att, scale, preatt, B * NH, T, q_);

    // vaccum (floatX) reuses inp buffer
    floatX* vaccum = inp;
    // need att as floatX and vv as floatX -> vaccum fp32 intermediate then convert
    {
        float* vacF = sycl::malloc_device<float>((size_t)B * NH * T * HS, q_);
        sycl_gemm_batch_vaccum(vacF, vv, att, T, HS, (int64_t)B * NH, q_);
