            if (i >= N) { return; }
            vaccum[i] = (floatX)vacF[i];
        }).wait();
        sycl::free(vacF, q_);
    }
    unpermute_out(out, vaccum, B, T, NH, HS, q_);
}

inline void attention_backward(floatX* dinp, floatX* dqkvr, floatX* datt, floatX* scratch,
                               const floatX* dout,
                               const floatX* qkvr, const floatX* att,
                               int B, int T, int C, int NH, sycl::queue& q_) {
    NVTX_RANGE_FN();
    const int HS = C / NH;
    const floatX *qq, *kk, *vv;
    qq = qkvr + 0 * (size_t)B * T * C;
    kk = qkvr + 1 * (size_t)B * T * C;
    vv = qkvr + 2 * (size_t)B * T * C;
    floatX *dq, *dk, *dv;
    dq = dqkvr + 0 * (size_t)B * T * C;
    dk = dqkvr + 1 * (size_t)B * T * C;
    dv = dqkvr + 2 * (size_t)B * T * C;

    // scratch (floatX, B*T*C) holds unpermuted dout
    unpermute_backward(scratch, dout, B, T, NH, HS, q_);
    // datt (floatX BNH*T*T): fp32 intermediate then convert
    {
        float* dattF = sycl::malloc_device<float>((size_t)B * NH * T * T, q_);
        sycl_gemm_batch_datt(dattF, vv, scratch, T, HS, (int64_t)B * NH, q_);
        size_t N = (size_t)B * NH * T * T;
        constexpr size_t BLOCK = 256;
        size_t nblocks = CEIL_DIV(N, BLOCK);
        q_.parallel_for(sycl::range<1>(nblocks * BLOCK), [=](sycl::id<1> id) {
            size_t i = id[0];
            if (i >= N) { return; }
            datt[i] = (floatX)dattF[i];
        }).wait();
        sycl::free(dattF, q_);
    }
    // dv
    {
        float* dvF = sycl::malloc_device<float>((size_t)B * NH * T * HS, q_);
        sycl_gemm_batch_dv(dvF, scratch, att, T, HS, (int64_t)B * NH, q_);
        size_t N = (size_t)B * NH * T * HS;
        constexpr size_t BLOCK = 256;
        size_t nblocks = CEIL_DIV(N, BLOCK);
        q_.parallel_for(sycl::range<1>(nblocks * BLOCK), [=](sycl::id<1> id) {
            size_t i = id[0];
            if (i >= N) { return; }
            dv[i] = (floatX)dvF[i];
        }).wait();
        sycl::free(dvF, q_);
    }
    const float scale = 1.0f / sqrtf((float)HS);
    softmax_backward_sycl(datt, att, B * NH, T, scale, q_);
    const floatX* dpreatt = datt;
    // dq
    {
        float* dqF = sycl::malloc_device<float>((size_t)B * NH * T * HS, q_);
        sycl_gemm_batch_dq(dqF, kk, dpreatt, T, HS, (int64_t)B * NH, q_);
        size_t N = (size_t)B * NH * T * HS;
        constexpr size_t BLOCK = 256;
        size_t nblocks = CEIL_DIV(N, BLOCK);
        q_.parallel_for(sycl::range<1>(nblocks * BLOCK), [=](sycl::id<1> id) {
            size_t i = id[0];
            if (i >= N) { return; }
            dq[i] = (floatX)dqF[i];
        }).wait();
        sycl::free(dqF, q_);
    }
    // dk
    {
        float* dkF = sycl::malloc_device<float>((size_t)B * NH * T * HS, q_);
        sycl_gemm_batch_dk(dkF, qq, dpreatt, T, HS, (int64_t)B * NH, q_);
        size_t N = (size_t)B * NH * T * HS;
        constexpr size_t BLOCK = 256;
        size_t nblocks = CEIL_DIV(N, BLOCK);
        q_.parallel_for(sycl::range<1>(nblocks * BLOCK), [=](sycl::id<1> id) {
            size_t i = id[0];
            if (i >= N) { return; }
            dk[i] = (floatX)dkF[i];
        }).wait();
        sycl::free(dkF, q_);
    }
    permute_qkv_backward(dinp, dq, dk, dv, B, T, NH, HS, q_);
}

#endif

/*
Attention (SYCL port of attention.cuh, non-flash path = llm.c default).
Uses oneMath batched GEMM with fp32 intermediates + SYCL softmax/permute kernels.
*/
#ifndef ATTENTION_SYCL_H
#define ATTENTION_SYCL_H

#include <assert.h>
#include <sycl/sycl.hpp>
// llmc internal imports
#include "sycl_common.h"
#include "sycl_utils.h"
#include "blas_common.h"
#include "matmul.h"

// ----------------------------------------------------------------------------
// SYCL kernels

// split (B, T, 3*C) inp into q,k,v each (B, NH, T, HS)
inline void permute_qkv(floatX* q, floatX* k, floatX* v, const floatX* inp,
                        int B, int T, int NH, int HS, sycl::queue& q_) {
    size_t N = (size_t)B * NH * T * HS;
    constexpr size_t BLOCK = 256;
    size_t nblocks = CEIL_DIV(N, BLOCK);
    q_.parallel_for(sycl::range<1>(nblocks * BLOCK), [=](sycl::id<1> id) {
        size_t idx = id[0];
        if (idx >= N) { return; }
        size_t d = HS;
        size_t b = idx / ((size_t)NH * T * d);
        size_t rest = idx % ((size_t)NH * T * d);
        size_t nh = rest / ((size_t)T * d);
        rest = rest % ((size_t)T * d);
        size_t n = rest / d;
        size_t dd = rest % d;
        size_t inp_idx = (b * (size_t)T * 3 * NH * d) + (n * 3 * NH * d) + (nh * d) + dd;
        q[idx] = inp[inp_idx];
        k[idx] = inp[inp_idx + (size_t)NH * d];
        v[idx] = inp[inp_idx + 2 * (size_t)NH * d];
    }).wait();
}

inline void permute_qkv_backward(floatX* dinp, const floatX* dq, const floatX* dk, const floatX* dv,
                                 int B, int T, int NH, int HS, sycl::queue& q_) {
    size_t N = (size_t)B * NH * T * HS;
    constexpr size_t BLOCK = 256;
    size_t nblocks = CEIL_DIV(N, BLOCK);
    q_.parallel_for(sycl::range<1>(nblocks * BLOCK), [=](sycl::id<1> id) {
        size_t idx = id[0];
        if (idx >= N) { return; }
        size_t d = HS;
        size_t b = idx / ((size_t)NH * T * d);
        size_t rest = idx % ((size_t)NH * T * d);
        size_t nh = rest / ((size_t)T * d);
        rest = rest % ((size_t)T * d);
        size_t n = rest / d;
        size_t dd = rest % d;
        size_t inp_idx = (b * (size_t)T * 3 * NH * d) + (n * 3 * NH * d) + (nh * d) + dd;
        dinp[inp_idx] = dq[idx];
        dinp[inp_idx + (size_t)NH * d] = dk[idx];
        dinp[inp_idx + 2 * (size_t)NH * d] = dv[idx];
    }).wait();
}

// vaccum (B, NH, T, HS) -> out (B, T, C)
inline void unpermute_out(floatX* out, const floatX* vaccum, int B, int T, int NH, int HS, sycl::queue& q_) {
    size_t N = (size_t)B * T * NH * HS;
    constexpr size_t BLOCK = 256;
    size_t nblocks = CEIL_DIV(N, BLOCK);
    q_.parallel_for(sycl::range<1>(nblocks * BLOCK), [=](sycl::id<1> id) {
        size_t idx = id[0];
        if (idx >= N) { return; }
        size_t d = HS;
        size_t b = idx / ((size_t)NH * T * d);
        size_t rest = idx % ((size_t)NH * T * d);
        size_t nh = rest / ((size_t)T * d);
        rest = rest % ((size_t)T * d);
        size_t n = rest / d;
        size_t dd = rest % d;
        size_t other_idx = (b * (size_t)NH * T * d) + (n * NH * d) + (nh * d) + dd;
        out[other_idx] = vaccum[idx];
    }).wait();
}

inline void unpermute_backward(floatX* dinp, const floatX* dout, int B, int T, int NH, int HS, sycl::queue& q_) {
    size_t N = (size_t)B * T * NH * HS;
    constexpr size_t BLOCK = 256;
    size_t nblocks = CEIL_DIV(N, BLOCK);
    q_.parallel_for(sycl::range<1>(nblocks * BLOCK), [=](sycl::id<1> id) {
        size_t idx = id[0];
        if (idx >= N) { return; }
        size_t d = HS;
        size_t b = idx / ((size_t)NH * T * d);
        size_t rest = idx % ((size_t)NH * T * d);
        size_t nh = rest / ((size_t)T * d);
        rest = rest % ((size_t)T * d);
        size_t n = rest / d;
        size_t dd = rest % d;
        size_t other_idx = (b * (size_t)NH * T * d) + (n * NH * d) + (nh * d) + dd;
        dinp[idx] = (floatX)dout[other_idx];
    }).wait();
}

// autoregressive causal softmax: out(N*T*T) = softmax(inp * scale), per row causal. inp fp32, out floatX.
inline void softmax_forward_sycl(floatX* out, float scale, const float* inp, int N, int T, sycl::queue& q_) {
    // one work-group per row
    constexpr size_t WG = 32;
    q_.parallel_for(sycl::nd_range<1>(sycl::range<1>((size_t)N * T * WG), sycl::range<1>(WG)),
        [=](sycl::nd_item<1> item) {
        size_t idx = item.get_group(0);
        if (idx >= (size_t)N * T) { return; }
        size_t lid = item.get_local_id(0);
        auto sg = item.get_sub_group();
        size_t own_pos = idx % (size_t)T;
        const float* x = inp + idx * (size_t)T;
        const float FLT_MAXF = 340282346638528859811704183484516925440.0f;
        float maxval = -FLT_MAXF;
        float sumval = 0.f;
        // online softmax over causal prefix
        for (size_t i = lid; i <= own_pos; i += WG) {
            float v = x[i] * scale;
            float old = maxval;
            maxval = sycl::fmax(maxval, v);
            sumval *= sycl::exp(old - maxval);
            sumval += sycl::exp(v - maxval);
        }
        float gmax = sycl::reduce_over_group(sg, maxval, sycl::maximum<float>());
        sumval *= sycl::exp(maxval - gmax);
        float gsum = sycl::reduce_over_group(sg, sumval, sycl::plus<float>());
        float norm = 1.f / gsum;
        floatX* o = out + idx * (size_t)T;
        for (size_t i = lid; i <= own_pos; i += WG) {
            float ev = sycl::exp(x[i] * scale - gmax);
            o[i] = (floatX)(ev * norm);
        }
    }).wait();
}

// datt (B*NH*T*T, floatX) inplace -> dpreatt; att floatX; scale applied.
inline void softmax_backward_sycl(floatX* datt, const floatX* att, int BNH, int T, float scale, sycl::queue& q_) {
    constexpr size_t WG = 32;
    size_t rows = (size_t)BNH * T;
    q_.parallel_for(sycl::nd_range<1>(sycl::range<1>(rows * WG), sycl::range<1>(WG)),
        [=](sycl::nd_item<1> item) {
        size_t idx = item.get_group(0);
        if (idx >= rows) { return; }
        size_t lid = item.get_local_id(0);
        auto sg = item.get_sub_group();
        size_t t = idx % (size_t)T;
        const floatX* att_row = att + idx * (size_t)T;
        const floatX* datt_row = datt + idx * (size_t)T;
        float local = 0.f;
        for (size_t t2 = lid; t2 <= t; t2 += WG) {
            local += (float)att_row[t2] * (float)datt_row[t2];
        }
        local = sycl::reduce_over_group(sg, local, sycl::plus<float>());
        floatX* dp = datt + idx * (size_t)T;
        for (size_t t3 = lid; t3 < (size_t)T; t3 += WG) {
            if (t3 <= t) {
                float acc = (float)att_row[t3] * ((float)datt_row[t3] - local);
                dp[t3] = (floatX)(scale * acc);
            } else {
                dp[t3] = (floatX)0.f;
            }
        }
    }).wait();
}

// ----------------------------------------------------------------------------
// launchers

inline void attention_forward(floatX* out, floatX* qkvr, floatX* att,
                              floatX* inp,
                              int B, int T, int C, int NH, sycl::queue& q_) {
    NVTX_RANGE_FN();
    const int HS = C / NH;
    floatX *qq, *kk, *vv;
    qq = qkvr + 0 * (size_t)B * T * C;
    kk = qkvr + 1 * (size_t)B * T * C;
    vv = qkvr + 2 * (size_t)B * T * C;
    permute_qkv(qq, kk, vv, inp, B, T, NH, HS, q_);

    // preatt (fp32) in inp buffer reinterpreted
    float* preatt = (float*)inp;
    sycl_gemm_batch_preatt(preatt, kk, qq, T, HS, (int64_t)B * NH, q_);

    float scale = 1.f / sqrtf((float)HS);
    softmax_forward_sycl(att, scale, preatt, B * NH, T, q_);

    // vaccum (floatX) reuses inp buffer
    floatX* vaccum = inp;
    // need att as floatX and vv as floatX -> vaccum fp32 intermediate then convert
    {
        float* vacF = sycl::malloc_device<float>((size_t)B * NH * T * HS, q_);
        sycl_gemm_batch_vaccum(vacF, vv, att, T, HS, (int64_t)B * NH, q_);
        size_t N = (size_t)B * NH * T * HS;
        constexpr size_t BLOCK = 256;
        size_t nblocks = CEIL_DIV(N, BLOCK);
        q_.parallel_for(sycl::range<1>(nblocks * BLOCK), [=](sycl::id<1> id) {
            size_t i = id[0];
            if (i >= N) { return; }
            vaccum[i] = (floatX)vacF[i];
        }).wait();
        sycl::free(vacF, q_);
    }
    unpermute_out(out, vaccum, B, T, NH, HS, q_);
}

inline void attention_backward(floatX* dinp, floatX* dqkvr, floatX* datt, floatX* scratch,
                               const floatX* dout,
                               const floatX* qkvr, const floatX* att,
                               int B, int T, int C, int NH, sycl::queue& q_) {
    NVTX_RANGE_FN();
    const int HS = C / NH;
    const floatX *qq, *kk, *vv;
    qq = qkvr + 0 * (size_t)B * T * C;
    kk = qkvr + 1 * (size_t)B * T * C;
    vv = qkvr + 2 * (size_t)B * T * C;
    floatX *dq, *dk, *dv;
    dq = dqkvr + 0 * (size_t)B * T * C;
    dk = dqkvr + 1 * (size_t)B * T * C;
    dv = dqkvr + 2 * (size_t)B * T * C;

    // scratch (floatX, B*T*C) holds unpermuted dout
    unpermute_backward(scratch, dout, B, T, NH, HS, q_);
    // datt (floatX BNH*T*T): fp32 intermediate then convert
    {
        float* dattF = sycl::malloc_device<float>((size_t)B * NH * T * T, q_);
        sycl_gemm_batch_datt(dattF, vv, scratch, T, HS, (int64_t)B * NH, q_);
        size_t N = (size_t)B * NH * T * T;
        constexpr size_t BLOCK = 256;
        size_t nblocks = CEIL_DIV(N, BLOCK);
        q_.parallel_for(sycl::range<1>(nblocks * BLOCK), [=](sycl::id<1> id) {
            size_t i = id[0];
            if (i >= N) { return; }
            datt[i] = (floatX)dattF[i];
        }).wait();
        sycl::free(dattF, q_);
    }
    // dv
    {
        float* dvF = sycl::malloc_device<float>((size_t)B * NH * T * HS, q_);
        sycl_gemm_batch_dv(dvF, scratch, att, T, HS, (int64_t)B * NH, q_);
        size_t N = (size_t)B * NH * T * HS;
        constexpr size_t BLOCK = 256;
        size_t nblocks = CEIL_DIV(N, BLOCK);
        q_.parallel_for(sycl::range<1>(nblocks * BLOCK), [=](sycl::id<1> id) {
            size_t i = id[0];
            if (i >= N) { return; }
            dv[i] = (floatX)dvF[i];
        }).wait();
        sycl::free(dvF, q_);
    }
    const float scale = 1.0f / sqrtf((float)HS);
    softmax_backward_sycl(datt, att, B * NH, T, scale, q_);
    const floatX* dpreatt = datt;
    // dq
    {
        float* dqF = sycl::malloc_device<float>((size_t)B * NH * T * HS, q_);
        sycl_gemm_batch_dq(dqF, kk, dpreatt, T, HS, (int64_t)B * NH, q_);
        size_t N = (size_t)B * NH * T * HS;
        constexpr size_t BLOCK = 256;
        size_t nblocks = CEIL_DIV(N, BLOCK);
        q_.parallel_for(sycl::range<1>(nblocks * BLOCK), [=](sycl::id<1> id) {
            size_t i = id[0];
            if (i >= N) { return; }
            dq[i] = (floatX)dqF[i];
        }).wait();
        sycl::free(dqF, q_);
    }
    // dk
    {
        float* dkF = sycl::malloc_device<float>((size_t)B * NH * T * HS, q_);
        sycl_gemm_batch_dk(dkF, qq, dpreatt, T, HS, (int64_t)B * NH, q_);
        size_t N = (size_t)B * NH * T * HS;
        constexpr size_t BLOCK = 256;
        size_t nblocks = CEIL_DIV(N, BLOCK);
        q_.parallel_for(sycl::range<1>(nblocks * BLOCK), [=](sycl::id<1> id) {
            size_t i = id[0];
            if (i >= N) { return; }
            dk[i] = (floatX)dkF[i];
        }).wait();
        sycl::free(dkF, q_);
    }
    permute_qkv_backward(dinp, dq, dk, dv, B, T, NH, HS, q_);
}

#endif

/*
Fused Classifier (SYCL port of fused_classifier.cuh):
- Forwards the Cross Entropy Loss
- Never materializes the full normalized logits
- Kicks off the backward pass (logits -> dlogits) when WriteDLogits=true
*/
#ifndef FUSED_CLASSIFIER_SYCL_H
#define FUSED_CLASSIFIER_SYCL_H

#include <sycl/sycl.hpp>
// llmc internal imports
#include "sycl_common.h"
#include "sycl_utils.h"

// replaces logits with logit gradients when WriteDLogits=true
template <typename Type, bool WriteDLogits>
inline void fused_classifier(Type* logits, float* losses,
                             const float dloss, const int* targets,
                             int B, int T, int V, int P, std::bool_constant<WriteDLogits>, sycl::queue& q_) {
    NVTX_RANGE_FN();
    size_t N = (size_t)B * T;
    // one work-group per row
    constexpr size_t WG = 32;
    q_.parallel_for(sycl::nd_range<1>(sycl::range<1>(N * WG), sycl::range<1>(WG)),
        [=](sycl::nd_item<1> item) {
        // reverse order not needed for correctness; keep natural order
        size_t idx = item.get_group(0);
        if (idx >= N) { return; }
        size_t lid = item.get_local_id(0);
        auto sg = item.get_sub_group();
        int ix = targets[idx];
        const Type* row = logits + idx * (size_t)P;
        // online softmax max/sum over V (padded P, ignore padding)
        const float NEG_INF = -3.402823466e+38f;
        float tmax = NEG_INF, tsum = 0.f;
        for (int i = (int)lid; i < V; i += (int)WG) {
            float v = (float)row[i];
            float old = tmax;
            tmax = sycl::fmax(tmax, v);
            tsum *= sycl::exp(old - tmax);
            tsum += sycl::exp(v - tmax);
        }
        float bmax = sycl::reduce_over_group(sg, tmax, sycl::maximum<float>());
        tsum *= sycl::exp(tmax - bmax);
        float bsum = sycl::reduce_over_group(sg, tsum, sycl::plus<float>());
        float scale = 1.f / bsum;
        float offset = bmax;
        if (lid == 0) {
            float prob = sycl::exp((float)row[ix] - offset) * scale;
            losses[idx] -= sycl::log(prob);
        }
        item.barrier(sycl::access::fence_space::local_space);
        Type* wrow = logits + idx * (size_t)P;
        for (int i = (int)lid; i < V; i += (int)WG) {
            float prob = sycl::exp((float)row[i] - offset) * scale;
            float indicator = (i == ix) ? 1.0f : 0.0f;
            float dlogit = (prob - indicator) * dloss;
            if constexpr (WriteDLogits) {
                wrow[i] = (Type)dlogit;
            }
        }
        // zero the padding explicitly when writing dlogits (keeps buffer clean)
        if constexpr (WriteDLogits) {
            for (int i = V + (int)lid; i < P; i += (int)WG) {
                wrow[i] = (Type)0.f;
            }
        }
    }).wait();
}

#endif

/*
AdamW optimizer (SYCL port of adamw.cuh), with llm.c's stochastic rounding
and determinism (per-tensor seed; same update math incl. lerp).
*/
#ifndef ADAMW_SYCL_H
#define ADAMW_SYCL_H

#include <sycl/sycl.hpp>
// llmc internal imports
#include "sycl_common.h"
#include "sycl_utils.h"

inline float sycl_lerp(float start, float end, float weight) {
    return sycl::fma(weight, end, sycl::fma(-weight, start, start));
}

template <typename Tp, typename Tg>
inline void adamw_update(Tp* params_memory, float* master_params_memory, Tg* grads_memory,
                         float* m_memory, float* v_memory, size_t num_parameters,
                         ptrdiff_t w_stride, ptrdiff_t g_stride, ptrdiff_t s_stride, int num_slices,
                         float learning_rate, float beta1, float beta2, int t, float eps, float weight_decay,
                         float grad_scale, unsigned int seed, sycl::queue& q_) {
    float beta1_correction = 1.0f - powf(beta1, t);
    float beta2_correction = 1.0f - powf(beta2, t);
    size_t total = num_parameters * (size_t)num_slices;
    constexpr size_t BLOCK = 512;
    size_t nblocks = CEIL_DIV(total, BLOCK);
    q_.parallel_for(sycl::range<1>(nblocks * BLOCK), [=](sycl::id<1> id) {
        size_t lin = id[0];
        if (lin >= total) { return; }
        size_t slice = lin / num_parameters;
        size_t idx = lin % num_parameters;
        Tp* p = params_memory + slice * (size_t)w_stride;
        float* mp = master_params_memory ? master_params_memory + slice * (size_t)s_stride : nullptr;
        Tg* g = grads_memory + slice * (size_t)g_stride;
        float* m = m_memory + slice * (size_t)s_stride;
        float* v = v_memory + slice * (size_t)s_stride;
        float grad = grad_scale * (float)g[idx];
        float mv = m[idx];
        float vv = v[idx];
        mv = sycl_lerp(grad, mv, beta1);
        m[idx] = mv;
        vv = sycl_lerp(grad * grad, vv, beta2);
        v[idx] = vv;
        mv /= beta1_correction;
        vv /= beta2_correction;
        float old_param = (mp != nullptr) ? mp[idx] : (float)p[idx];
        float param = old_param - (learning_rate * (mv / (sycl::sqrt(vv) + eps) + weight_decay * old_param));
        if constexpr (std::is_same<Tp, float>::value) {
            p[idx] = param;
        } else {
            // match CUDA indexing: Get2dNoiseUint(threadIdx.x, blockIdx.x*blockDim.x + blockIdx.y, seed)
            // here: thread = lin % 512, blockX = lin / 512 ... approximate with same formula:
            unsigned int tx = (unsigned int)(idx % 512);
            unsigned int bx = (unsigned int)(slice + idx / 512);
            unsigned int random = Get2dNoiseUint((int)tx, (int)bx, seed);
            p[idx] = stochastic_rounding_bf16(param, random);
        }
        if (mp != nullptr) { mp[idx] = param; }
    }).wait();
}

template <typename Tp>
inline void init_from_master(Tp* params_memory, float* master_params_memory, size_t num_parameters,
                             ptrdiff_t w_stride, ptrdiff_t s_stride, int num_slices,
                             unsigned int seed, sycl::queue& q_) {
    size_t total = num_parameters * (size_t)num_slices;
    constexpr size_t BLOCK = 512;
    size_t nblocks = CEIL_DIV(total, BLOCK);
    q_.parallel_for(sycl::range<1>(nblocks * BLOCK), [=](sycl::id<1> id) {
        size_t lin = id[0];
        if (lin >= total) { return; }
        size_t slice = lin / num_parameters;
        size_t idx = lin % num_parameters;
        Tp* p = params_memory + slice * (size_t)w_stride;
        float* mp = master_params_memory + slice * (size_t)s_stride;
        if constexpr (std::is_same<Tp, float>::value) {
            p[idx] = mp[idx];
        } else {
            unsigned int tx = (unsigned int)(idx % 512);
            unsigned int bx = (unsigned int)(slice + idx / 512);
            unsigned int random = Get2dNoiseUint((int)tx, (int)bx, seed);
            p[idx] = stochastic_rounding_bf16(mp[idx], random);
        }
    }).wait();
}

