template<class Float>
inline void global_sum_deterministic(float* result, const Float* values, size_t count, sycl::queue& q) {
    if (count == 0) {
        q.memset(result, 0, sizeof(float)).wait();
        return;
    }
    constexpr size_t BLOCK = 1024;
    // partial sums, one per thread
    float* partial = sycl::malloc_device<float>(BLOCK, q);
    q.parallel_for(sycl::nd_range<1>(sycl::range<1>(BLOCK), sycl::range<1>(BLOCK)),
        [=](sycl::nd_item<1> item) {
        size_t tid = item.get_local_id(0);
        float thread_sum = 0.f;
        for (size_t i = tid; i < count; i += BLOCK) {
            thread_sum += (float)values[i];
        }
        // sub-group reduce first
        auto sg = item.get_sub_group();
        thread_sum = sycl::reduce_over_group(sg, thread_sum, sycl::plus<float>());
        // one thread per sub-group writes to local memory
        sycl::local_accessor<float, 1> scratch(sycl::range<1>(BLOCK / SYCL_SUBGROUP_SIZE), item);
        size_t sgid = sg.get_group_id()[0];
        size_t nsg = sg.get_group_range()[0];
        if (sg.get_local_id()[0] == 0) {
            scratch[sgid] = thread_sum;
        }
        item.barrier(sycl::access::fence_space::local_space);
        // final reduce by first sub-group
        float block_val = 0.f;
        if (sgid == 0) {
            float v = (sg.get_local_id()[0] < nsg) ? scratch[sg.get_local_id()[0]] : 0.f;
            block_val = sycl::reduce_over_group(sg, v, sycl::plus<float>());
            if (sg.get_local_id()[0] == 0) {
                partial[0] = block_val;
            }
        }
        (void)tid;
    }).wait();
    q.memcpy(result, partial, sizeof(float)).wait();
    sycl::free(partial, q);
}

